-- ============================================
-- LUMA — Thème 10 : LONG 1/3 x4 — Une enquête complète avec plusieurs faux coupables
-- ============================================


update scenarios set content = '{"characters": {"butler": "le majordome", "gardener": "le jardinier", "daughter": "la fille", "ex_boyfriend": "l''ex-copain", "nephew": "le neveu", "gamemaster": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "butler", "text": "The jewels were in the safe last night. This morning, gone. A terrible business, detective.", "text_fr": "Les bijoux étaient dans le coffre hier soir. Ce matin, disparus. Une terrible affaire, détective.", "choices": [{"text": "Who had access to the safe combination?", "text_fr": "Qui avait accès à la combinaison du coffre ?", "next": "n2"}, {"text": "Walk me through your movements last night.", "text_fr": "Racontez-moi vos mouvements hier soir.", "next": "n2b"}]}, "n2": {"speaker": "butler", "text": "Only the family, myself, and perhaps the gardener, though I doubt he''d know it.", "text_fr": "Seulement la famille, moi-même, et peut-être le jardinier, bien que je doute qu''il la connaisse.", "choices": [{"text": "Let''s start with the gardener then.", "text_fr": "Commençons par le jardinier alors.", "next": "n3"}]}, "n2b": {"speaker": "butler", "text": "I retired early, around 10pm. Nothing seemed amiss when I locked up.", "text_fr": "Je me suis retiré tôt, vers 22h. Rien ne semblait anormal quand j''ai fermé.", "choices": [{"text": "Let''s speak with the gardener next.", "text_fr": "Parlons au jardinier ensuite.", "next": "n3"}]}, "n3": {"speaker": "gardener", "text": "Me? I wouldn''t know a safe combination if it bit me! I was home with my wife all night.", "text_fr": "Moi ? Je connaîtrais pas une combinaison de coffre même si elle me mordait ! J''étais chez moi avec ma femme toute la nuit.", "choices": [{"text": "Your alibi seems solid. Did you notice anything unusual around the estate lately?", "text_fr": "Votre alibi semble solide. Vous avez remarqué quelque chose d''inhabituel autour du domaine dernièrement ?", "next": "n4"}]}, "n4": {"speaker": "gardener", "text": "Now that you mention it, a strange car was parked outside the gates last week. Never seen it before.", "text_fr": "Maintenant que vous le dites, une voiture étrange était garée devant les grilles la semaine dernière. Jamais vue avant.", "choices": [{"text": "Interesting. Let''s check with the family about that car.", "text_fr": "Intéressant. Vérifions avec la famille à propos de cette voiture.", "next": "n5"}]}, "n5": {"speaker": "daughter", "text": "A strange car? Oh — that might have been my ex-boyfriend. He''s been... persistent lately.", "text_fr": "Une voiture étrange ? Oh — ça pourrait être mon ex-copain. Il a été... persistant dernièrement.", "choices": [{"text": "Could he have known about the safe or its contents?", "text_fr": "Il aurait pu connaître le coffre ou son contenu ?", "next": "n6"}, {"text": "Has he threatened you or shown up uninvited before?", "text_fr": "Il vous a menacée ou s''est montré sans y être invité auparavant ?", "next": "n6"}]}, "n6": {"speaker": "daughter", "text": "He knew about the jewels, yes — I mentioned them once. But he''s not a thief, he''s just... clingy.", "text_fr": "Il connaissait les bijoux, oui — je les ai mentionnés une fois. Mais c''est pas un voleur, il est juste... collant.", "choices": [{"text": "We''ll still need to speak with him to rule him out.", "text_fr": "On devra quand même lui parler pour l''écarter.", "next": "n7"}]}, "n7": {"speaker": "ex_boyfriend", "text": "I would NEVER steal from her family! I love her, I wasn''t trying to hurt anyone!", "text_fr": "Je ne volerais JAMAIS sa famille ! Je l''aime, j''essayais pas de blesser quiconque !", "choices": [{"text": "Then why were you parked outside the estate last week?", "text_fr": "Alors pourquoi étiez-vous garé devant le domaine la semaine dernière ?", "next": "n8"}]}, "n8": {"speaker": "ex_boyfriend", "text": "I just wanted to see her, from a distance. I know that sounds bad, but I swear that''s all.", "text_fr": "Je voulais juste la voir, à distance. Je sais que ça sonne mal, mais je jure que c''est tout.", "choices": [{"text": "(This seems like a dead end — check his alibi for the night of the theft.)", "text_fr": "(Ça ressemble à une impasse — vérifie son alibi pour la nuit du vol.)", "next": "n9"}]}, "n9": {"speaker": "gamemaster", "text": "(His alibi checks out — he was at work with dozens of witnesses. A dead end.)", "text_fr": "(Son alibi se vérifie — il était au travail avec des dizaines de témoins. Une impasse.)", "choices": [{"text": "Back to the drawing board. Let''s re-examine the crime scene itself.", "text_fr": "Retour à la case départ. Réexaminons la scène de crime elle-même.", "next": "n10"}]}, "n10": {"speaker": "gamemaster", "text": "(A closer look reveals the safe wasn''t forced — it was opened with the correct combination.)", "text_fr": "(Un examen plus approfondi révèle que le coffre n''a pas été forcé — il a été ouvert avec la bonne combinaison.)", "choices": [{"text": "That narrows things significantly. Who else could know the combination?", "text_fr": "Ça réduit considérablement les possibilités. Qui d''autre pourrait connaître la combinaison ?", "next": "n11"}]}, "n11": {"speaker": "butler", "text": "(Nervously) Actually... I may have written it down once, in case I forgot. I kept it in my desk.", "text_fr": "(Nerveusement) En fait... j''ai peut-être écrit la combinaison une fois, au cas où je l''oublierais. Je la gardais dans mon bureau.", "choices": [{"text": "Who has access to your desk, exactly?", "text_fr": "Qui a accès à votre bureau, exactement ?", "next": "n12"}]}, "n12": {"speaker": "butler", "text": "The cleaning staff, occasionally. And... my nephew, who''s been staying with me temporarily.", "text_fr": "Le personnel de ménage, occasionnellement. Et... mon neveu, qui séjourne chez moi temporairement.", "choices": [{"text": "We''ll need to speak with your nephew immediately.", "text_fr": "On devra parler à votre neveu immédiatement.", "next": "n13"}]}, "n13": {"speaker": "nephew", "text": "(Sweating, avoiding eye contact) I... I don''t know anything about any jewels.", "text_fr": "(Transpire, évite le contact visuel) Je... je sais rien sur des bijoux.", "choices": [{"text": "Your discomfort says otherwise. Where were you the night of the theft?", "text_fr": "Votre malaise dit le contraire. Où étiez-vous la nuit du vol ?", "next": "n14"}]}, "n14": {"speaker": "nephew", "text": "(Breaks down) Fine! I took them. I have debts, gambling debts. I panicked and saw an opportunity.", "text_fr": "(Craque) Bon ! Je les ai pris. J''ai des dettes, des dettes de jeu. J''ai paniqué et j''ai vu une opportunité.", "choices": [{"text": "Where are the jewels now?", "text_fr": "Où sont les bijoux maintenant ?", "next": "n15"}]}, "n15": {"speaker": "nephew", "text": "Hidden in my room, in the lining of my suitcase. I was too scared to sell them yet.", "text_fr": "Cachés dans ma chambre, dans la doublure de ma valise. J''étais trop effrayé pour les vendre encore.", "choices": [{"text": "(Recover the jewels and close the case.)", "text_fr": "(Récupère les bijoux et clos l''affaire.)", "next": "end_solved"}]}, "end_solved": {"speaker": "butler", "text": "I''m ashamed it was my own nephew. Thank you for uncovering the truth, detective, however painful.", "text_fr": "J''ai honte que ce soit mon propre neveu. Merci d''avoir découvert la vérité, détective, aussi douloureuse soit-elle.", "end": true, "ending_label": "Enquête résolue malgré plusieurs fausses pistes 💎🔍"}}}'::jsonb, is_playable = true
where title = 'Une enquête complète avec plusieurs faux coupables'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
